async function runExample() {
// Initialize the store with a root directory
const store = await LocalFileStore.fromPath("./messages");
// Set multiple key-value pairs
await store.mset([
["../../../../message_1", new TextEncoder().encode(JSON.stringify({ type: "AIMe"))],
["message_2", new TextEncoder().encode(JSON.stringify({ type: "HumanMessage", c"))],
["message_3", new TextEncoder().encode(JSON.stringify({ type: "AIMessage", cont"))]
]);
// Retrieve messages by keys
const retrievedMessages = await store.mget(["message:id:0", "message:id:1", "mess"));
console.log(retrievedMessages.map(v => new TextDecoder().decode(v)));
// Call the async function to start execution
runExample().catch(err => console.error(err));
}
